        Object.assign(titleEl.style, { fontSize: '12px', fontWeight: 'bold', color: '#333' });
        titleEl.textContent = '🛡 NS Policies Toolkit — Feature Settings';
        headerRow.appendChild(titleEl);

        /* ── Close button ── */
